function photoFallback(img,name){img.hidden=true;img.insertAdjacentHTML('afterend',`<div class="animal-photo" role="img" aria-label="Photo unavailable for ${name}"></div>`)}
async function loadPhoto(img){if(img.dataset.loaded)return;img.dataset.loaded='1';const pages=[img.dataset.page,img.dataset.scientific].filter(Boolean);for(const page of pages){try{const r=await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(page)}`);if(!r.ok)continue;const d=await r.json(),src=d.thumbnail?.source;if(src){img.src=src;return}}catch(e){}}photoFallback(img,img.alt.replace(' photograph',''))}
function renderWildlife(){const q=animalSearch.value.toLowerCase().trim();const rows=wildlife.filter(a=>(animalKind==='all'||a[2]===animalKind)&&(!q||a.join(' ').toLowerCase().includes(q)));animalResultCount.textContent=`${rows.length} ${rows.length===1?'field entry':'field entries'} shown`;clearAnimalSearch.hidden=!q;animalGrid.innerHTML=rows.length?rows.map(a=>{const hasSound=!!soundFiles[a[0]],photo=photoFiles[a[0]];return `<article><img class="animal-photo" ${photo?`src="${photo}" data-direct="1" onerror="this.removeAttribute('data-direct');loadPhoto(this)"`:''} data-page="${a[4]}" data-scientific="${a[1]}" alt="${a[0]} photograph" loading="lazy"><div class="animal-body"><h2>${a[0]}</h2><p>${a[1]}</p><div class="animal-meta"><span>${a[2]}</span><span>${a[3]}</span></div><div class="animal-actions"><button class="animal-profile" data-profile="${a[1]}">Open field entry</button><button class="animal-sound" data-sound="${a[0]}" ${hasSound?'':'disabled'}>${hasSound?'▶ Hear real call':'No recording yet'}</button></div><small class="photo-credit">Photo: Wikimedia Commons</small></div></article>`}).join(''):'<div class="animal-empty">No species matches that search.</div>';const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){loadPhoto(e.target);observer.unobserve(e.target)}}),{rootMargin:'250px'});document.querySelectorAll('.animal-photo[data-page]:not([data-direct])').forEach(x=>observer.observe(x));document.querySelectorAll('.animal-sound:not(:disabled)').forEach(b=>b.addEventListener('click',()=>playSound(b)))}
function playSound(button){if(playingAudio)playingAudio.pause();const file=soundFiles[button.dataset.sound];playingAudio=new Audio(`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}`);button.textContent='Loading…';playingAudio.addEventListener('playing',()=>button.textContent='■ Stop');playingAudio.addEventListener('ended',()=>button.textContent='▶ Hear real call');playingAudio.addEventListener('error',()=>{button.textContent='Recording unavailable';button.disabled=true});playingAudio.play().catch(()=>{button.textContent='Tap again to play'})}
document.querySelectorAll('#wildlifeFilters button').forEach(button=>button.addEventListener('click',()=>{animalKind=button.dataset.kind;document.querySelectorAll('#wildlifeFilters button').forEach(x=>x.classList.toggle('selected',x===button));renderWildlife()}));animalSearch.addEventListener('input',renderWildlife);clearAnimalSearch.addEventListener('click',()=>{animalSearch.value='';if(faunaMode==='guide')renderWildlife();else animalSearch.dispatchEvent(new Event('input'));animalSearch.focus()});renderWildlife();

