const faunaCountry=document.getElementById('faunaCountry'),biodiversityControls=document.getElementById('biodiversityControls'),databaseNote=document.getElementById('databaseNote'),wildlifeFilters=document.getElementById('wildlifeFilters');let faunaMode='guide',gbifOffset=0,gbifSeen=new Set();
