document.querySelectorAll('#faunaMode button').forEach(button=>button.addEventListener('click',()=>{faunaMode=button.dataset.mode;document.querySelectorAll('#faunaMode button').forEach(x=>x.classList.toggle('selected',x===button));const live=faunaMode==='database';biodiversityControls.hidden=!live;databaseNote.hidden=!live;wildlifeFilters.hidden=live;if(live){animalGrid.innerHTML='<div class="database-status">Choose a country to browse its most frequently published animal records. Add a search term to find a particular species.</div>'}else renderWildlife()}));
