document.getElementById('searchBiodiversity').addEventListener('click',()=>searchGbif(true));faunaCountry.addEventListener('change',()=>{if(faunaCountry.value)searchGbif(true)});
async function browseCountryRecords(country){const response=await fetch(`https://api.gbif.org/v1/occurrence/search?country=${country}&taxon_key=1&limit=0&facet=speciesKey&facet_limit=60`);if(!response.ok)throw new Error(response.status);const data=await response.json(),facets=data.facets?.find(item=>item.field==='SPECIES_KEY')?.counts||data.facets?.[0]?.counts||[],rows=(await Promise.all(facets.slice(0,60).map(async item=>{try{const taxon=await fetch(`https://api.gbif.org/v1/species/${item.name}`).then(result=>result.ok?result.json():null);return taxon?{...taxon,records:item.count}:null}catch(error){return null}}))).filter(Boolean);const countryName=africanCountries.find(item=>item[0]===country)?.[1]||country;animalGrid.innerHTML=rows.length?`<div class="database-status country-record-heading"><strong>${rows.length} frequently recorded animal species in ${countryName}</strong><span>Ordered by GBIF record volume; this is not the country’s total species count.</span></div>${rows.map(item=>`<article class="gbif-card"><img class="animal-photo" data-page="${item.scientificName||item.canonicalName||''}" alt="${item.canonicalName||item.scientificName} photograph" loading="lazy"><div class="animal-body"><h2>${item.vernacularName||item.canonicalName||item.scientificName}</h2><p>${item.scientificName||''}</p><div class="animal-meta"><span>${item.class||item.order||'Animal'}</span><span>${Number(item.records).toLocaleString()} GBIF records</span></div><div class="animal-actions"><button class="animal-profile" data-profile="${item.scientificName||item.canonicalName}">Open field entry</button></div></div></article>`).join('')}`:'<div class="database-status">No country records were returned.</div>';document.querySelectorAll('.animal-photo[data-page]').forEach(loadPhoto)}
async function searchGbif(reset){const q=animalSearch.value.trim(),country=faunaCountry.value;if(!country){animalGrid.innerHTML='<div class="database-status">Select a country first.</div>';return}if(q.length===1){animalGrid.innerHTML='<div class="database-status">Enter at least two characters, or clear the search box to browse country records.</div>';return}if(reset){gbifOffset=0;gbifSeen=new Set();animalGrid.innerHTML='<div class="database-status">Checking published biodiversity records…</div>'}try{if(!q){await browseCountryRecords(country);return}const url=`https://api.gbif.org/v1/occurrence/search?country=${country}&q=${encodeURIComponent(q)}&limit=100&offset=${gbifOffset}`,r=await fetch(url),d=await r.json(),unique=d.results.filter(x=>{const key=x.taxonKey||x.scientificName;if(!key||gbifSeen.has(key))return false;gbifSeen.add(key);return true});const cards=unique.map(x=>{const name=x.vernacularName||x.species||x.genericName||x.scientificName,scientific=x.scientificName||'',kind=x.class||x.order||'Animal',photo=(x.media||[]).find(m=>m.type==='StillImage'||m.identifier)?.identifier;return `<article class="gbif-card">${photo?`<img class="animal-photo" src="${photo}" alt="${name} photograph" loading="lazy" referrerpolicy="no-referrer">`:`<img class="animal-photo" data-page="${scientific}" alt="${name} photograph" loading="lazy">`}<div class="animal-body"><h2>${name}</h2><p>${scientific}</p><div class="animal-meta"><span>${kind}</span><span>${x.family||'Family not recorded'}</span></div><div class="animal-actions"><small class="photo-credit">GBIF occurrence record</small></div></div></article>`}).join('');if(reset)animalGrid.innerHTML=cards||'<div class="database-status">No matching records found. Try a broader term or scientific name.</div>';else animalGrid.querySelector('.load-more')?.remove(),animalGrid.insertAdjacentHTML('beforeend',cards);document.querySelectorAll('.animal-photo[data-page]').forEach(loadPhoto);gbifOffset+=100;if(!d.end&&unique.length)animalGrid.insertAdjacentHTML('beforeend','<button class="primary load-more" type="button">Load more records <span>→</span></button>'),animalGrid.querySelector('.load-more')?.addEventListener('click',()=>searchGbif(false))}catch(e){animalGrid.innerHTML='<div class="database-status">The live biodiversity service is unavailable. Your offline African starter guide still works.</div>'}}
